input.newString:
    $rounder = new self();
    $rounder->number = (float) $number;
    $rounder->digits = $digits;
    $rounder->showTypeDetails(Calculation::getInstance(), $number);

    if ($number == 0.0) {
        return 0.0;
    }

    if (PHP_VERSION_ID >= 80400) {
        return round(
            (float) (string) $number,
            $digits,
            RoundingMode::AwayFromZero //* @phpstan-ignore-line
        );
    }

    if ($number < 0.0) {
        return round($number - 0.5 * 0.1 ** $digits, $digits, PHP_ROUND_HALF_DOWN);
    }

    return round($number + 0.5 * 0.1 ** $digits, $digits, PHP_ROUND_HALF_DOWN);
}

